-- 카카오 로컬 API 인근시설 실데이터 (아파트·대학·지하철역·대형마트)
-- 기존 목업(source=manual, mock-*) + 이전 수집분(crawler) 제거 후 재삽입 → 재실행 안전
delete from public.local_info where source = 'manual' and external_id like 'mock-%';
delete from public.local_info where source = 'crawler';

on conflict (category, external_id, source) do update set name = excluded.name, region = excluded.region, address = excluded.address, lat = excluded.lat, lng = excluded.lng, data = excluded.data, synced_at = now();

-- 총 239건